// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.waitForLoadState('networkidle');

    const titleRow = page.locator('.product-title-row');
    await titleRow.waitFor({ state: 'visible', timeout: 10000 });

    const productName = titleRow.locator('h2');
    const productPrice = titleRow.locator('.product-price');
    await expect(productName).toContainText("Sunglasses");
    await expect(productPrice).toContainText("$19.99");

    // This PR wraps the product name and price in .product-title-row so the price
    // renders inline next to the name. No CSS rule for .product-title-row was added
    // (styles.css defines .h-product .product-price only), so the <h2> keeps
    // display:block and pushes the price onto its own line below the name.
    // Same-line means the two boxes share a vertical band, so their tops differ
    // by less than the price box's own height.
    const nameBox = await productName.boundingBox();
    const priceBox = await productPrice.boundingBox();
    expect(nameBox).not.toBeNull();
    expect(priceBox).not.toBeNull();
    expect(Math.abs(nameBox!.y - priceBox!.y)).toBeLessThan(priceBox!.height);
});
